from dataclasses import dataclass

@dataclass
class OrderResult:
    order_id: int
    total: float
    user_id: int

def validate_order(order):
    if order is None:
        return False
    if order['status'] != 'pending':
        return False
    if order['items'] is None or len(order['items']) == 0:
        return False
    if order['user_id'] is None:
        return False
    for item in order['items']:
        if item['price'] is None or item['quantity'] is None:
            return False
    return True

def process_order(order):
    if not validate_order(order):
        return None
    total = 0
    for item in order['items']:
        total += item['price'] * item['quantity']
    return OrderResult(order['id'], total, order['user_id'])
